  from jsonb_array_elements('[{"body":"\ndeclare\n  row_data jsonb;\n  row_kind text;\n  row_key text;\n  row_day text;\n  row_payload jsonb;\n  row_deleted boolean;\n  row_unset boolean;\n  row_time timestamptz;\n  row_id uuid;\n  old_row jsonb;\n  old_time timestamptz;\n  old_id uuid;\n  expected_body jsonb;\n  applied integer;\n  answer text;\n  replies jsonb := ''[]''::jsonb;\nbegin\n  if auth.uid() is null or not exists (\n    select 1 from public.profiles p\n    where p.id = p_profile_id and p.owner_id = auth.uid()\n  ) then\n    raise exception ''profile unavailable'' using errcode = ''42501'';\n  end if;\n  if p_mutations is null or jsonb_typeof(p_mutations) <> ''array''\n     or jsonb_array_length(p_mutations) > 100\n     or pg_column_size(p_mutations) > 262144 then\n    raise exception ''invalid mutation batch'' using errcode = ''22023'';\n  end if;\n\n  for row_data in select value from jsonb_array_elements(p_mutations) loop\n    if jsonb_typeof(row_data) <> ''object''\n       or row_data->>''changedAt'' !~\n         ''^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\\.[0-9]{1,3})?(Z|[+-][0-9]{2}:[0-9]{2})$''\n       or row_data->>''mutationId'' is null then\n      raise exception ''invalid mutation envelope'' using errcode = ''22023'';\n    end if;\n    row_kind := row_data->>''kind'';\n    row_time := (row_data->>''changedAt'')::timestamptz;\n    row_id := (row_data->>''mutationId'')::uuid;\n    applied := null;\n    old_row := null;\n\n    case row_kind\n      when ''progress'' then\n        row_key := row_data->>''key'';\n        if coalesce(length(row_key), 0) not between 1 and 512\n           or jsonb_typeof(row_data->''deleted'') <> ''boolean'' then\n          raise exception ''invalid progress key or deletion state'' using errcode = ''22023'';\n        end if;\n        row_deleted := (row_data->>''deleted'')::boolean;\n        row_payload := row_data->''payload'';\n        if row_payload is null or row_deleted <> (row_payload = ''null''::jsonb) or\n           (not row_deleted and (jsonb_typeof(row_payload) <> ''object''\n             or not (row_payload ?& array[''status'',''effort'',''daily'',''note''])\n             or jsonb_typeof(row_payload->''daily'') not in (''boolean'',''null'')\n             or jsonb_typeof(row_payload->''note'') not in (''string'',''null''))) then\n          raise exception ''invalid progress payload'' using errcode = ''22023'';\n        end if;\n        insert into public.progress as current\n          (profile_id,event_id,status,effort,daily_override,note,deleted,changed_at,mutation_id)\n          values (p_profile_id,row_key,\n            case when row_deleted then null else row_payload->>''status'' end,\n            case when row_deleted then null else row_payload->>''effort'' end,\n            case when row_deleted or row_payload->''daily'' = ''null''::jsonb then null\n              else (row_payload->>''daily'')::boolean end,\n            case when row_deleted then null else row_payload->>''note'' end,\n            row_deleted,row_time,row_id)\n          on conflict (profile_id,event_id) do update set\n            status=excluded.status, effort=excluded.effort,\n            daily_override=excluded.daily_override, note=excluded.note,\n            deleted=excluded.deleted, changed_at=excluded.changed_at,\n            mutation_id=excluded.mutation_id, received_at=now()\n          where (excluded.changed_at,excluded.mutation_id) >\n            (current.changed_at,current.mutation_id)\n          returning 1 into applied;\n        if applied is null then\n          select to_jsonb(t), t.changed_at, t.mutation_id into old_row, old_time, old_id\n            from public.progress t where t.profile_id=p_profile_id and t.event_id=row_key;\n          expected_body := jsonb_build_object(''event_id'',row_key,\n            ''status'',case when row_deleted then null else row_payload->>''status'' end,\n            ''effort'',case when row_deleted then null else row_payload->>''effort'' end,\n            ''daily_override'',case when row_deleted or row_payload->''daily''=''null''::jsonb\n              then null else (row_payload->>''daily'')::boolean end,\n            ''note'',case when row_deleted then null else row_payload->>''note'' end,\n            ''deleted'',row_deleted);\n        end if;\n\n      when ''daily'' then\n        row_key := row_data->''key''->>''subjectId'';\n        row_day := row_data->''key''->>''dayKey'';\n        if coalesce(length(row_key),0) not between 1 and 512\n           or row_day !~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}$''\n           or jsonb_typeof(row_data->''completed'') <> ''boolean'' then\n          raise exception ''invalid daily mutation'' using errcode = ''22023'';\n        end if;\n        insert into public.daily_marks as current\n          (profile_id,subject_id,day_key,completed,changed_at,mutation_id)\n          values (p_profile_id,row_key,row_day,(row_data->>''completed'')::boolean,row_time,row_id)\n          on conflict (profile_id,subject_id,day_key) do update set\n            completed=excluded.completed, changed_at=excluded.changed_at,\n            mutation_id=excluded.mutation_id, received_at=now()\n          where (excluded.changed_at,excluded.mutation_id) >\n            (current.changed_at,current.mutation_id)\n          returning 1 into applied;\n        if applied is null then\n          select to_jsonb(t), t.changed_at, t.mutation_id into old_row, old_time, old_id\n            from public.daily_marks t where t.profile_id=p_profile_id\n              and t.subject_id=row_key and t.day_key=row_day;\n          expected_body := jsonb_build_object(''subject_id'',row_key,\n            ''day_key'',row_day,''completed'',(row_data->>''completed'')::boolean);\n        end if;\n\n      when ''ignored'' then\n        row_key := row_data->>''key'';\n        if coalesce(length(row_key),0) not between 1 and 512\n           or jsonb_typeof(row_data->''ignored'') <> ''boolean'' then\n          raise exception ''invalid ignored mutation'' using errcode = ''22023'';\n        end if;\n        insert into public.ignored as current\n          (profile_id,event_id,ignored,changed_at,mutation_id)\n          values (p_profile_id,row_key,(row_data->>''ignored'')::boolean,row_time,row_id)\n          on conflict (profile_id,event_id) do update set\n            ignored=excluded.ignored,changed_at=excluded.changed_at,\n            mutation_id=excluded.mutation_id,received_at=now()\n          where (excluded.changed_at,excluded.mutation_id) >\n            (current.changed_at,current.mutation_id)\n          returning 1 into applied;\n        if applied is null then\n          select to_jsonb(t), t.changed_at, t.mutation_id into old_row, old_time, old_id\n            from public.ignored t where t.profile_id=p_profile_id and t.event_id=row_key;\n          expected_body := jsonb_build_object(''event_id'',row_key,\n            ''ignored'',(row_data->>''ignored'')::boolean);\n        end if;\n\n      when ''preference'' then\n        row_key := row_data->>''key'';\n        row_payload := row_data->''value'';\n        if jsonb_typeof(row_data->''unset'') <> ''boolean'' or row_payload is null\n           or not public.sync_valid_preference(row_key,row_payload,\n             (row_data->>''unset'')::boolean) then\n          raise exception ''invalid preference mutation'' using errcode = ''22023'';\n        end if;\n        row_unset := (row_data->>''unset'')::boolean;\n        insert into public.preferences as current\n          (profile_id,key,value,unset,changed_at,mutation_id)\n          values (p_profile_id,row_key,row_payload,row_unset,row_time,row_id)\n          on conflict (profile_id,key) do update set\n            value=excluded.value,unset=excluded.unset,changed_at=excluded.changed_at,\n            mutation_id=excluded.mutation_id,received_at=now()\n          where (excluded.changed_at,excluded.mutation_id) >\n            (current.changed_at,current.mutation_id)\n          returning 1 into applied;\n        if applied is null then\n          select to_jsonb(t), t.changed_at, t.mutation_id into old_row, old_time, old_id\n            from public.preferences t where t.profile_id=p_profile_id and t.key=row_key;\n          expected_body := jsonb_build_object(''key'',row_key,''value'',row_payload,''unset'',row_unset);\n        end if;\n\n      when ''customGame'', ''customEvent'' then\n        row_key := row_data->>''key'';\n        row_payload := row_data->''payload'';\n        if jsonb_typeof(row_data->''deleted'') <> ''boolean'' then\n          raise exception ''invalid custom deletion state'' using errcode = ''22023'';\n        end if;\n        row_deleted := (row_data->>''deleted'')::boolean;\n        if row_payload is null or row_deleted <> (row_payload = ''null''::jsonb) or\n           (not row_deleted and (jsonb_typeof(row_payload) <> ''object''\n             or row_payload->>''id'' is distinct from row_key)) then\n          raise exception ''invalid custom payload'' using errcode = ''22023'';\n        end if;\n        if row_kind = ''customGame'' then\n          if not row_deleted and (not (row_payload ?& array[''id'',''name'',''hue'',''at''])\n             or jsonb_typeof(row_payload->''name'') <> ''string''\n             or jsonb_typeof(row_payload->''hue'') <> ''string''\n             or jsonb_typeof(row_payload->''at'') <> ''string'') then\n            raise exception ''invalid custom game envelope'' using errcode = ''22023'';\n          end if;\n          insert into public.custom_games as current\n            (profile_id,local_id,payload,deleted,changed_at,mutation_id)\n            values (p_profile_id,row_key,\n              case when row_deleted then null else row_payload end,row_deleted,row_time,row_id)\n            on conflict (profile_id,local_id) do update set\n              payload=excluded.payload,deleted=excluded.deleted,\n              changed_at=excluded.changed_at,mutation_id=excluded.mutation_id,received_at=now()\n            where (excluded.changed_at,excluded.mutation_id) >\n              (current.changed_at,current.mutation_id)\n            returning 1 into applied;\n          if applied is null then\n            select to_jsonb(t), t.changed_at, t.mutation_id into old_row, old_time, old_id\n              from public.custom_games t where t.profile_id=p_profile_id and t.local_id=row_key;\n          end if;\n        else\n          if not row_deleted and (not (row_payload ?& array[\n              ''id'',''game'',''title'',''type'',''startsAt'',''startPrecision'',''endsAt'',\n              ''endPrecision'',''repeat'',''at'',''updatedAt''])\n             or jsonb_typeof(row_payload->''game'') <> ''string''\n             or jsonb_typeof(row_payload->''title'') <> ''string''\n             or jsonb_typeof(row_payload->''type'') <> ''string'') then\n            raise exception ''invalid custom event envelope'' using errcode = ''22023'';\n          end if;\n          insert into public.custom_events as current\n            (profile_id,local_id,payload,deleted,changed_at,mutation_id)\n            values (p_profile_id,row_key,\n              case when row_deleted then null else row_payload end,row_deleted,row_time,row_id)\n            on conflict (profile_id,local_id) do update set\n              payload=excluded.payload,deleted=excluded.deleted,\n              changed_at=excluded.changed_at,mutation_id=excluded.mutation_id,received_at=now()\n            where (excluded.changed_at,excluded.mutation_id) >\n              (current.changed_at,current.mutation_id)\n            returning 1 into applied;\n          if applied is null then\n            select to_jsonb(t), t.changed_at, t.mutation_id into old_row, old_time, old_id\n              from public.custom_events t where t.profile_id=p_profile_id and t.local_id=row_key;\n          end if;\n        end if;\n        if applied is null then\n          expected_body := jsonb_build_object(''local_id'',row_key,\n            ''payload'',case when row_deleted then null else row_payload end,\n            ''deleted'',row_deleted);\n        end if;\n\n      else\n        raise exception ''unknown mutation kind'' using errcode = ''22023'';\n    end case;\n\n    if applied is not null then\n      answer := ''accepted'';\n    elsif old_id = row_id and old_time <> row_time then\n      raise exception ''mutation ID reused with a different version'' using errcode = ''22023'';\n    elsif old_time = row_time and old_id = row_id then\n      if (old_row - ''profile_id'' - ''changed_at'' - ''mutation_id'' - ''received_at'')\n         is distinct from expected_body then\n        raise exception ''conflicting payload for logical version'' using errcode = ''22023'';\n      end if;\n      answer := ''accepted'';\n    else\n      answer := ''superseded'';\n    end if;\n    replies := replies || jsonb_build_array(\n      jsonb_build_object(''mutationId'',row_id,''outcome'',answer));\n  end loop;\n  return replies;\nend;\n","definition":"CREATE OR REPLACE FUNCTION public.apply_profile_mutations(p_profile_id uuid, p_mutations jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  row_data jsonb;\n  row_kind text;\n  row_key text;\n  row_day text;\n  row_payload jsonb;\n  row_deleted boolean;\n  row_unset boolean;\n  row_time timestamptz;\n  row_id uuid;\n  old_row jsonb;\n  old_time timestamptz;\n  old_id uuid;\n  expected_body jsonb;\n  applied integer;\n  answer text;\n  replies jsonb := ''[]''::jsonb;\nbegin\n  if auth.uid() is null or not exists (\n    select 1 from public.profiles p\n    where p.id = p_profile_id and p.owner_id = auth.uid()\n  ) then\n    raise exception ''profile unavailable'' using errcode = ''42501'';\n  end if;\n  if p_mutations is null or jsonb_typeof(p_mutations) <> ''array''\n     or jsonb_array_length(p_mutations) > 100\n     or pg_column_size(p_mutations) > 262144 then\n    raise exception ''invalid mutation batch'' using errcode = ''22023'';\n  end if;\n\n  for row_data in select value from jsonb_array_elements(p_mutations) loop\n    if jsonb_typeof(row_data) <> ''object''\n       or row_data->>''changedAt'' !~\n         ''^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\\.[0-9]{1,3})?(Z|[+-][0-9]{2}:[0-9]{2})$''\n       or row_data->>''mutationId'' is null then\n      raise exception ''invalid mutation envelope'' using errcode = ''22023'';\n    end if;\n    row_kind := row_data->>''kind'';\n    row_time := (row_data->>''changedAt'')::timestamptz;\n    row_id := (row_data->>''mutationId'')::uuid;\n    applied := null;\n    old_row := null;\n\n    case row_kind\n      when ''progress'' then\n        row_key := row_data->>''key'';\n        if coalesce(length(row_key), 0) not between 1 and 512\n           or jsonb_typeof(row_data->''deleted'') <> ''boolean'' then\n          raise exception ''invalid progress key or deletion state'' using errcode = ''22023'';\n        end if;\n        row_deleted := (row_data->>''deleted'')::boolean;\n        row_payload := row_data->''payload'';\n        if row_payload is null or row_deleted <> (row_payload = ''null''::jsonb) or\n           (not row_deleted and (jsonb_typeof(row_payload) <> ''object''\n             or not (row_payload ?& array[''status'',''effort'',''daily'',''note''])\n             or jsonb_typeof(row_payload->''daily'') not in (''boolean'',''null'')\n             or jsonb_typeof(row_payload->''note'') not in (''string'',''null''))) then\n          raise exception ''invalid progress payload'' using errcode = ''22023'';\n        end if;\n        insert into public.progress as current\n          (profile_id,event_id,status,effort,daily_override,note,deleted,changed_at,mutation_id)\n          values (p_profile_id,row_key,\n            case when row_deleted then null else row_payload->>''status'' end,\n            case when row_deleted then null else row_payload->>''effort'' end,\n            case when row_deleted or row_payload->''daily'' = ''null''::jsonb then null\n              else (row_payload->>''daily'')::boolean end,\n            case when row_deleted then null else row_payload->>''note'' end,\n            row_deleted,row_time,row_id)\n          on conflict (profile_id,event_id) do update set\n            status=excluded.status, effort=excluded.effort,\n            daily_override=excluded.daily_override, note=excluded.note,\n            deleted=excluded.deleted, changed_at=excluded.changed_at,\n            mutation_id=excluded.mutation_id, received_at=now()\n          where (excluded.changed_at,excluded.mutation_id) >\n            (current.changed_at,current.mutation_id)\n          returning 1 into applied;\n        if applied is null then\n          select to_jsonb(t), t.changed_at, t.mutation_id into old_row, old_time, old_id\n            from public.progress t where t.profile_id=p_profile_id and t.event_id=row_key;\n          expected_body := jsonb_build_object(''event_id'',row_key,\n            ''status'',case when row_deleted then null else row_payload->>''status'' end,\n            ''effort'',case when row_deleted then null else row_payload->>''effort'' end,\n            ''daily_override'',case when row_deleted or row_payload->''daily''=''null''::jsonb\n              then null else (row_payload->>''daily'')::boolean end,\n            ''note'',case when row_deleted then null else row_payload->>''note'' end,\n            ''deleted'',row_deleted);\n        end if;\n\n      when ''daily'' then\n        row_key := row_data->''key''->>''subjectId'';\n        row_day := row_data->''key''->>''dayKey'';\n        if coalesce(length(row_key),0) not between 1 and 512\n           or row_day !~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}$''\n           or jsonb_typeof(row_data->''completed'') <> ''boolean'' then\n          raise exception ''invalid daily mutation'' using errcode = ''22023'';\n        end if;\n        insert into public.daily_marks as current\n          (profile_id,subject_id,day_key,completed,changed_at,mutation_id)\n          values (p_profile_id,row_key,row_day,(row_data->>''completed'')::boolean,row_time,row_id)\n          on conflict (profile_id,subject_id,day_key) do update set\n            completed=excluded.completed, changed_at=excluded.changed_at,\n            mutation_id=excluded.mutation_id, received_at=now()\n          where (excluded.changed_at,excluded.mutation_id) >\n            (current.changed_at,current.mutation_id)\n          returning 1 into applied;\n        if applied is null then\n          select to_jsonb(t), t.changed_at, t.mutation_id into old_row, old_time, old_id\n            from public.daily_marks t where t.profile_id=p_profile_id\n              and t.subject_id=row_key and t.day_key=row_day;\n          expected_body := jsonb_build_object(''subject_id'',row_key,\n            ''day_key'',row_day,''completed'',(row_data->>''completed'')::boolean);\n        end if;\n\n      when ''ignored'' then\n        row_key := row_data->>''key'';\n        if coalesce(length(row_key),0) not between 1 and 512\n           or jsonb_typeof(row_data->''ignored'') <> ''boolean'' then\n          raise exception ''invalid ignored mutation'' using errcode = ''22023'';\n        end if;\n        insert into public.ignored as current\n          (profile_id,event_id,ignored,changed_at,mutation_id)\n          values (p_profile_id,row_key,(row_data->>''ignored'')::boolean,row_time,row_id)\n          on conflict (profile_id,event_id) do update set\n            ignored=excluded.ignored,changed_at=excluded.changed_at,\n            mutation_id=excluded.mutation_id,received_at=now()\n          where (excluded.changed_at,excluded.mutation_id) >\n            (current.changed_at,current.mutation_id)\n          returning 1 into applied;\n        if applied is null then\n          select to_jsonb(t), t.changed_at, t.mutation_id into old_row, old_time, old_id\n            from public.ignored t where t.profile_id=p_profile_id and t.event_id=row_key;\n          expected_body := jsonb_build_object(''event_id'',row_key,\n            ''ignored'',(row_data->>''ignored'')::boolean);\n        end if;\n\n      when ''preference'' then\n        row_key := row_data->>''key'';\n        row_payload := row_data->''value'';\n        if jsonb_typeof(row_data->''unset'') <> ''boolean'' or row_payload is null\n           or not public.sync_valid_preference(row_key,row_payload,\n             (row_data->>''unset'')::boolean) then\n          raise exception ''invalid preference mutation'' using errcode = ''22023'';\n        end if;\n        row_unset := (row_data->>''unset'')::boolean;\n        insert into public.preferences as current\n          (profile_id,key,value,unset,changed_at,mutation_id)\n          values (p_profile_id,row_key,row_payload,row_unset,row_time,row_id)\n          on conflict (profile_id,key) do update set\n            value=excluded.value,unset=excluded.unset,changed_at=excluded.changed_at,\n            mutation_id=excluded.mutation_id,received_at=now()\n          where (excluded.changed_at,excluded.mutation_id) >\n            (current.changed_at,current.mutation_id)\n          returning 1 into applied;\n        if applied is null then\n          select to_jsonb(t), t.changed_at, t.mutation_id into old_row, old_time, old_id\n            from public.preferences t where t.profile_id=p_profile_id and t.key=row_key;\n          expected_body := jsonb_build_object(''key'',row_key,''value'',row_payload,''unset'',row_unset);\n        end if;\n\n      when ''customGame'', ''customEvent'' then\n        row_key := row_data->>''key'';\n        row_payload := row_data->''payload'';\n        if jsonb_typeof(row_data->''deleted'') <> ''boolean'' then\n          raise exception ''invalid custom deletion state'' using errcode = ''22023'';\n        end if;\n        row_deleted := (row_data->>''deleted'')::boolean;\n        if row_payload is null or row_deleted <> (row_payload = ''null''::jsonb) or\n           (not row_deleted and (jsonb_typeof(row_payload) <> ''object''\n             or row_payload->>''id'' is distinct from row_key)) then\n          raise exception ''invalid custom payload'' using errcode = ''22023'';\n        end if;\n        if row_kind = ''customGame'' then\n          if not row_deleted and (not (row_payload ?& array[''id'',''name'',''hue'',''at''])\n             or jsonb_typeof(row_payload->''name'') <> ''string''\n             or jsonb_typeof(row_payload->''hue'') <> ''string''\n             or jsonb_typeof(row_payload->''at'') <> ''string'') then\n            raise exception ''invalid custom game envelope'' using errcode = ''22023'';\n          end if;\n          insert into public.custom_games as current\n            (profile_id,local_id,payload,deleted,changed_at,mutation_id)\n            values (p_profile_id,row_key,\n              case when row_deleted then null else row_payload end,row_deleted,row_time,row_id)\n            on conflict (profile_id,local_id) do update set\n              payload=excluded.payload,deleted=excluded.deleted,\n              changed_at=excluded.changed_at,mutation_id=excluded.mutation_id,received_at=now()\n            where (excluded.changed_at,excluded.mutation_id) >\n              (current.changed_at,current.mutation_id)\n            returning 1 into applied;\n          if applied is null then\n            select to_jsonb(t), t.changed_at, t.mutation_id into old_row, old_time, old_id\n              from public.custom_games t where t.profile_id=p_profile_id and t.local_id=row_key;\n          end if;\n        else\n          if not row_deleted and (not (row_payload ?& array[\n              ''id'',''game'',''title'',''type'',''startsAt'',''startPrecision'',''endsAt'',\n              ''endPrecision'',''repeat'',''at'',''updatedAt''])\n             or jsonb_typeof(row_payload->''game'') <> ''string''\n             or jsonb_typeof(row_payload->''title'') <> ''string''\n             or jsonb_typeof(row_payload->''type'') <> ''string'') then\n            raise exception ''invalid custom event envelope'' using errcode = ''22023'';\n          end if;\n          insert into public.custom_events as current\n            (profile_id,local_id,payload,deleted,changed_at,mutation_id)\n            values (p_profile_id,row_key,\n              case when row_deleted then null else row_payload end,row_deleted,row_time,row_id)\n            on conflict (profile_id,local_id) do update set\n              payload=excluded.payload,deleted=excluded.deleted,\n              changed_at=excluded.changed_at,mutation_id=excluded.mutation_id,received_at=now()\n            where (excluded.changed_at,excluded.mutation_id) >\n              (current.changed_at,current.mutation_id)\n            returning 1 into applied;\n          if applied is null then\n            select to_jsonb(t), t.changed_at, t.mutation_id into old_row, old_time, old_id\n              from public.custom_events t where t.profile_id=p_profile_id and t.local_id=row_key;\n          end if;\n        end if;\n        if applied is null then\n          expected_body := jsonb_build_object(''local_id'',row_key,\n            ''payload'',case when row_deleted then null else row_payload end,\n            ''deleted'',row_deleted);\n        end if;\n\n      else\n        raise exception ''unknown mutation kind'' using errcode = ''22023'';\n    end case;\n\n    if applied is not null then\n      answer := ''accepted'';\n    elsif old_id = row_id and old_time <> row_time then\n      raise exception ''mutation ID reused with a different version'' using errcode = ''22023'';\n    elsif old_time = row_time and old_id = row_id then\n      if (old_row - ''profile_id'' - ''changed_at'' - ''mutation_id'' - ''received_at'')\n         is distinct from expected_body then\n        raise exception ''conflicting payload for logical version'' using errcode = ''22023'';\n      end if;\n      answer := ''accepted'';\n    else\n      answer := ''superseded'';\n    end if;\n    replies := replies || jsonb_build_array(\n      jsonb_build_object(''mutationId'',row_id,''outcome'',answer));\n  end loop;\n  return replies;\nend;\n$function$\n","metadata":{"argumentModes":null,"argumentNames":["p_profile_id","p_mutations"],"arguments":"p_profile_id uuid, p_mutations jsonb","binary":null,"configuration":["search_path=\"\""],"cost":100,"kind":"f","language":"plpgsql","leakproof":false,"parallel":"u","result":"jsonb","returnsSet":false,"rows":0,"securityDefiner":true,"sqlBody":null,"strict":false,"support":null,"volatility":"v"},"name":"public.apply_profile_mutations"},{"body":"\ndeclare\n  account_id uuid := auth.uid();\n  result_id uuid;\nbegin\n  if account_id is null then\n    raise exception ''authentication required'' using errcode = ''42501'';\n  end if;\n  insert into public.profiles (owner_id, name, is_default)\n    values (account_id, ''Default'', true)\n    on conflict (owner_id) where is_default do nothing\n    returning id into result_id;\n  if result_id is null then\n    select id into result_id from public.profiles\n      where owner_id = account_id and is_default;\n  end if;\n  if result_id is null then\n    raise exception ''default profile unavailable'';\n  end if;\n  return result_id;\nend;\n","definition":"CREATE OR REPLACE FUNCTION public.ensure_default_profile()\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  account_id uuid := auth.uid();\n  result_id uuid;\nbegin\n  if account_id is null then\n    raise exception ''authentication required'' using errcode = ''42501'';\n  end if;\n  insert into public.profiles (owner_id, name, is_default)\n    values (account_id, ''Default'', true)\n    on conflict (owner_id) where is_default do nothing\n    returning id into result_id;\n  if result_id is null then\n    select id into result_id from public.profiles\n      where owner_id = account_id and is_default;\n  end if;\n  if result_id is null then\n    raise exception ''default profile unavailable'';\n  end if;\n  return result_id;\nend;\n$function$\n","metadata":{"argumentModes":null,"argumentNames":null,"arguments":"","binary":null,"configuration":["search_path=\"\""],"cost":100,"kind":"f","language":"plpgsql","leakproof":false,"parallel":"u","result":"uuid","returnsSet":false,"rows":0,"securityDefiner":true,"sqlBody":null,"strict":false,"support":null,"volatility":"v"},"name":"public.ensure_default_profile"},{"body":"\n  select jsonb_typeof(value) = ''array'' and not exists (\n    select 1 from jsonb_array_elements(\n      case when jsonb_typeof(value) = ''array'' then value else ''[]''::jsonb end\n    ) as item(element)\n    where jsonb_typeof(item.element) <> ''string''\n       or (allowed is not null and not ((item.element #>> ''{}'') = any(allowed)))\n  );\n","definition":"CREATE OR REPLACE FUNCTION public.sync_text_array(value jsonb, allowed text[] DEFAULT NULL::text[])\n RETURNS boolean\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO ''''\nAS $function$\n  select jsonb_typeof(value) = ''array'' and not exists (\n    select 1 from jsonb_array_elements(\n      case when jsonb_typeof(value) = ''array'' then value else ''[]''::jsonb end\n    ) as item(element)\n    where jsonb_typeof(item.element) <> ''string''\n       or (allowed is not null and not ((item.element #>> ''{}'') = any(allowed)))\n  );\n$function$\n","metadata":{"argumentModes":null,"argumentNames":["value","allowed"],"arguments":"value jsonb, allowed text[] DEFAULT NULL::text[]","binary":null,"configuration":["search_path=\"\""],"cost":100,"kind":"f","language":"sql","leakproof":false,"parallel":"u","result":"boolean","returnsSet":false,"rows":0,"securityDefiner":false,"sqlBody":null,"strict":false,"support":null,"volatility":"i"},"name":"public.sync_text_array"},{"body":"\n  select case\n    when pref_unset then pref_key in (''knownGames'', ''gameOrder'')\n      and pref_value = ''null''::jsonb\n    when pref_key in (''hiddenGames'', ''knownGames'', ''gameOrder'') then\n      public.sync_text_array(pref_value)\n    when pref_key = ''visibleCategories'' then public.sync_text_array(pref_value,\n      array[''banner'',''event'',''challenge'',''login'',''shop'',''maintenance''])\n    when pref_key = ''focusGame'' then jsonb_typeof(pref_value) in (''string'', ''null'')\n    when pref_key = ''region'' then pref_value::text in (''\"america\"'',''\"europe\"'',''\"asia\"'')\n    when pref_key = ''sort'' then pref_value::text in (''\"ending\"'',''\"doing\"'')\n    when pref_key = ''view'' then pref_value::text in (''\"soon\"'',''\"timeline\"'')\n    when pref_key = ''timelineGroup'' then pref_value::text in (''\"game\"'',''\"ending\"'')\n    when pref_key = ''theme'' then pref_value::text in (''\"dark\"'',''\"light\"'',''\"system\"'')\n    when pref_key = ''timelineDayWidth'' then jsonb_typeof(pref_value) = ''number''\n    when pref_key in (''showUpcoming'',''timelineSplitUpcoming'',''detectDaily'',\n      ''showChores'',''showCompleted'',''showIgnored'',''regionConfirmed'',''onboarded'')\n      then jsonb_typeof(pref_value) = ''boolean''\n    else false\n  end;\n","definition":"CREATE OR REPLACE FUNCTION public.sync_valid_preference(pref_key text, pref_value jsonb, pref_unset boolean)\n RETURNS boolean\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO ''''\nAS $function$\n  select case\n    when pref_unset then pref_key in (''knownGames'', ''gameOrder'')\n      and pref_value = ''null''::jsonb\n    when pref_key in (''hiddenGames'', ''knownGames'', ''gameOrder'') then\n      public.sync_text_array(pref_value)\n    when pref_key = ''visibleCategories'' then public.sync_text_array(pref_value,\n      array[''banner'',''event'',''challenge'',''login'',''shop'',''maintenance''])\n    when pref_key = ''focusGame'' then jsonb_typeof(pref_value) in (''string'', ''null'')\n    when pref_key = ''region'' then pref_value::text in (''\"america\"'',''\"europe\"'',''\"asia\"'')\n    when pref_key = ''sort'' then pref_value::text in (''\"ending\"'',''\"doing\"'')\n    when pref_key = ''view'' then pref_value::text in (''\"soon\"'',''\"timeline\"'')\n    when pref_key = ''timelineGroup'' then pref_value::text in (''\"game\"'',''\"ending\"'')\n    when pref_key = ''theme'' then pref_value::text in (''\"dark\"'',''\"light\"'',''\"system\"'')\n    when pref_key = ''timelineDayWidth'' then jsonb_typeof(pref_value) = ''number''\n    when pref_key in (''showUpcoming'',''timelineSplitUpcoming'',''detectDaily'',\n      ''showChores'',''showCompleted'',''showIgnored'',''regionConfirmed'',''onboarded'')\n      then jsonb_typeof(pref_value) = ''boolean''\n    else false\n  end;\n$function$\n","metadata":{"argumentModes":null,"argumentNames":["pref_key","pref_value","pref_unset"],"arguments":"pref_key text, pref_value jsonb, pref_unset boolean","binary":null,"configuration":["search_path=\"\""],"cost":100,"kind":"f","language":"sql","leakproof":false,"parallel":"u","result":"boolean","returnsSet":false,"rows":0,"securityDefiner":false,"sqlBody":null,"strict":false,"support":null,"volatility":"i"},"name":"public.sync_valid_preference"}]'::jsonb) e(item)
), live as (select 'public.'||p.proname as name,
  pg_catalog.pg_get_functiondef(p.oid) as definition, p.prosrc as body,
  jsonb_build_object(
    'arguments',pg_catalog.pg_get_function_arguments(p.oid),
    'result',pg_catalog.pg_get_function_result(p.oid),
    'argumentNames',p.proargnames,'argumentModes',p.proargmodes,
    'language',l.lanname,'kind',p.prokind,'volatility',p.provolatile,
    'strict',p.proisstrict,'securityDefiner',p.prosecdef,
    'leakproof',p.proleakproof,'parallel',p.proparallel,
    'cost',p.procost,'rows',p.prorows,'returnsSet',p.proretset,
    'configuration',p.proconfig,'binary',p.probin,
    'support',case when p.prosupport=0 then null else p.prosupport::regproc::text end,
    'sqlBody',p.prosqlbody::text
  ) as metadata
  from pg_catalog.pg_proc p join pg_catalog.pg_language l on l.oid=p.prolang
  where p.pronamespace='public'::regnamespace and p.proname in
    ('sync_text_array','sync_valid_preference','ensure_default_profile','apply_profile_mutations')
  order by p.proname,p.oid::regprocedure::text), paired as (
  select coalesce(e.name,l.name) as name,e.definition as expected_definition,l.definition as live_definition,
    e.body as expected_body,l.body as live_body,e.metadata as expected_metadata,l.metadata as live_metadata
  from expected e full join live l on e.name=l.name
), components as (
  select name,section,expected,live from paired cross join lateral (values
    ('definition',expected_definition,live_definition),
    ('body',expected_body,live_body),
    ('metadata',expected_metadata::text,live_metadata::text),
    -- Remove the exact catalog body only, leaving the entire declaration and
    -- dollar-quote delimiters intact. No whitespace is normalized here.
    ('declaration',case when length(expected_body)>0 then replace(expected_definition,expected_body,'') end,
      case when length(live_body)>0 then replace(live_definition,live_body,'') end)
  ) c(section,expected,live)
)
select jsonb_build_object(
  'serverMajor',current_setting('server_version_num')::integer / 10000,
  'projectRefs',(select jsonb_agg(project_ref order by project_ref) from calendar_backup_control.project_identity),
  'expectedObjects',(select count(*) from expected),'liveObjects',(select count(*) from live),
  'hashEncoding','SHA-256 of UTF-8 text (metadata uses jsonb::text); diagnostic only',
  'functions',(select jsonb_agg(jsonb_build_object(
    'name',p.name,'type','FUNCTION',
    'sections',(select jsonb_agg(jsonb_build_object('section',c.section,
      'matches',c.expected is not distinct from c.live,
      'expectedSha256',encode(sha256(convert_to(c.expected,'UTF8')),'hex'),
      'liveSha256',encode(sha256(convert_to(c.live,'UTF8')),'hex')) order by c.section)
      from components c where c.name=p.name),
    'differentMetadata',(select coalesce(jsonb_agg(jsonb_build_object(
      'name',coalesce(e.key,l.key),'type','FUNCTION ATTRIBUTE',
      'change',case when e.key is null then 'live-only' when l.key is null then 'expected-only' else 'changed' end)
      order by coalesce(e.key,l.key)),'[]'::jsonb)
      from jsonb_each(p.expected_metadata) e full join jsonb_each(p.live_metadata) l on e.key=l.key
      where e.value is distinct from l.value),
    -- Specific investigation candidates only: these do NOT authorize any
    -- production normalization, including changes inside string literals.
    'bodyMatchesAfterCRLF',replace(p.expected_body,E'\r\n',E'\n')=replace(p.live_body,E'\r\n',E'\n'),
    'bodyMatchesAfterOuterNewlines',btrim(p.expected_body,E'\r\n')=btrim(p.live_body,E'\r\n'),
    'bodyMatchesAfterCRLFAndOuterNewlines',
      btrim(replace(p.expected_body,E'\r\n',E'\n'),E'\n')=btrim(replace(p.live_body,E'\r\n',E'\n'),E'\n')
  ) order by p.name) from paired p)
) as function_diagnostics;
